KG42.register("slice-clusters-3f73b12f5fb723dc0ccae4f9",{"id":"12-p2p_microgrid_trading::v142-d-K003","paper":"12-p2p_microgrid_trading","title":"Elecbay half-hour order formation, counterparty selection, and gate-closure permissions","source_pointer":"/clusters/46","node_ids":["COMP-b9841ac99d9d29b8","COMP-b3f649e90c1f17b9","KG31-f563e86a7a19f2a5","COMP-739917e3869e45a6","KG31-17d2981437295871","COMP-a774da994c2ca212","COMP-4fd16cbd90d234cb","COMP-3fcd5e2d02ec7c3f"],"rule_refs":["12-p2p_microgrid_trading::v141-c-R006","12-p2p_microgrid_trading::v141-c-R007","12-p2p_microgrid_trading::v141-c-R008","12-p2p_microgrid_trading::v141-c-R010","12-p2p_microgrid_trading::v141-c-R011","12-p2p_microgrid_trading::v141-c-R012","12-p2p_microgrid_trading::v141-c-R013"],"visible_rule_refs":["12-p2p_microgrid_trading::v141-c-R006","12-p2p_microgrid_trading::v141-c-R007","12-p2p_microgrid_trading::v141-c-R008","12-p2p_microgrid_trading::v141-c-R010","12-p2p_microgrid_trading::v141-c-R011","12-p2p_microgrid_trading::v141-c-R012","12-p2p_microgrid_trading::v141-c-R013"],"suppressed_rule_refs":[],"edges":[{"global_edge_id":"S-7d6be3efa52b74fc","source":"COMP-b9841ac99d9d29b8","target":"COMP-b3f649e90c1f17b9","type":"links","assertion_ids":["12-p2p_microgrid_trading::v141-c-R007::E::v141-c-R007-E001"],"rule_refs":["12-p2p_microgrid_trading::v141-c-R007"],"internal":false},{"global_edge_id":"S-557a79fdbde7f4c2","source":"COMP-b9841ac99d9d29b8","target":"KG31-f563e86a7a19f2a5","type":"links","assertion_ids":["12-p2p_microgrid_trading::v141-c-R008::E::v141-c-R008-E001"],"rule_refs":["12-p2p_microgrid_trading::v141-c-R008"],"internal":false},{"global_edge_id":"S-a5e6c1cd118f1bb1","source":"COMP-b3f649e90c1f17b9","target":"KG31-f563e86a7a19f2a5","type":"links","assertion_ids":["12-p2p_microgrid_trading::v141-c-R008::E::v141-c-R008-E002"],"rule_refs":["12-p2p_microgrid_trading::v141-c-R008"],"internal":false},{"global_edge_id":"S-331ec0c106ac6ba0","source":"COMP-739917e3869e45a6","target":"KG31-f563e86a7a19f2a5","type":"links","assertion_ids":["12-p2p_microgrid_trading::v141-c-R008::E::v141-c-R008-E003"],"rule_refs":["12-p2p_microgrid_trading::v141-c-R008"],"internal":false},{"global_edge_id":"S-991e3b7ca3dd5b60","source":"COMP-b9841ac99d9d29b8","target":"KG31-17d2981437295871","type":"links","assertion_ids":["12-p2p_microgrid_trading::v141-c-R010::E::v141-c-R010-E001"],"rule_refs":["12-p2p_microgrid_trading::v141-c-R010"],"internal":false},{"global_edge_id":"S-f9ce868610a537fa","source":"COMP-b3f649e90c1f17b9","target":"KG31-17d2981437295871","type":"links","assertion_ids":["12-p2p_microgrid_trading::v141-c-R010::E::v141-c-R010-E002"],"rule_refs":["12-p2p_microgrid_trading::v141-c-R010"],"internal":false}],"unresolved_rule_refs":[],"interface_annotations":[{"connection_id":"v142-d-K003-L001","from_chain_id":"v141-c-R013","to_chain_id":"v141-c-R006","kind":"complementary_scope","from_refs":["v141-c-R013::phi::v141-c-R013-C001"],"to_refs":["v141-c-R006::phi::v141-c-R006-C001"],"evidence_ids":["v141-b-g01-ev-21"],"rationale":"The energy required for a half-hour period constitutes the product content of a demand listing; the two chains respectively describe the object of trading and the submission activity."},{"connection_id":"v142-d-K003-L002","from_chain_id":"v141-c-R013","to_chain_id":"v141-c-R007","kind":"complementary_scope","from_refs":["v141-c-R013::phi::v141-c-R013-C001"],"to_refs":["v141-c-R007::phi::v141-c-R007-C002"],"evidence_ids":["v141-b-g01-ev-13","v141-b-g01-ev-21"],"rationale":"Surplus energy for a half-hour period constitutes the product content of a supply listing and connects to selling activities during the posting and bidding stages."},{"connection_id":"v142-d-K003-L003","from_chain_id":"v141-c-R006","to_chain_id":"v141-c-R007","kind":"functional_coupling","from_refs":["v141-c-R006::phi::v141-c-R006-C001"],"to_refs":["v141-c-R007::phi::v141-c-R007-C001"],"evidence_ids":["v141-b-g01-ev-15","v141-b-g01-ev-21"],"rationale":"In the seller-initiated path, the half-hour demand listed by buyers provides the information input for sellers to browse and place orders; this connection is used only under this alternative path."},{"connection_id":"v142-d-K003-L004","from_chain_id":"v141-c-R007","to_chain_id":"v141-c-R010","kind":"functional_coupling","from_refs":["v141-c-R007::phi::v141-c-R007-C002"],"to_refs":["v141-c-R010::phi::v141-c-R010-C001"],"evidence_ids":["v141-b-g01-ev-13","v141-b-g01-ev-14"],"rationale":"Seller listings provide supply information for buyers to browse and place orders, thereby supporting counterparty selection in orders."},{"connection_id":"v142-d-K003-L005","from_chain_id":"v141-c-R006","to_chain_id":"v141-c-R010","kind":"functional_coupling","from_refs":["v141-c-R006::phi::v141-c-R006-C001"],"to_refs":["v141-c-R010::phi::v141-c-R010-C002"],"evidence_ids":["v141-b-g01-ev-15","v141-b-g01-ev-21"],"rationale":"Buyer demand listings provide information for seller-initiated counterparty selection. This path is parallel to the path in which buyers browse supply; the two cannot be inferred to be steps that must be executed consecutively."},{"connection_id":"v142-d-K003-L006","from_chain_id":"v141-c-R006","to_chain_id":"v141-c-R008","kind":"functional_coupling","from_refs":["v141-c-R006::phi::v141-c-R006-C001"],"to_refs":["v141-c-R008::phi::v141-c-R008-C001"],"evidence_ids":["v141-b-g01-ev-21"],"rationale":"Demand listings and buyer orders are submitted through Elecbay, with R008 supplementing the receiving platform; submission does not mean that an order has been accepted."},{"connection_id":"v142-d-K003-L007","from_chain_id":"v141-c-R007","to_chain_id":"v141-c-R008","kind":"functional_coupling","from_refs":["v141-c-R007::phi::v141-c-R007-C002"],"to_refs":["v141-c-R008::phi::v141-c-R008-C002"],"evidence_ids":["v141-b-g01-ev-13","v141-b-g01-ev-21"],"rationale":"Supply listings are provided through Elecbay, connecting supply submission activities with the platform's reception responsibilities, without inferring that the platform itself completes the network feasibility assessment."},{"connection_id":"v142-d-K003-L008","from_chain_id":"v141-c-R011","to_chain_id":"v141-c-R012","kind":"complementary_scope","from_refs":["v141-c-R011::phi::v141-c-R011-C001"],"to_refs":["v141-c-R012::phi::v141-c-R012-C001"],"evidence_ids":["v141-b-g01-ev-28"],"rationale":"The same platform description grants consumers and prosumers their respective trading options. The scopes of these two types of entities jointly constitute the scope of order participants, but the entity nodes are not merged."},{"connection_id":"v142-d-K003-L009","from_chain_id":"v141-c-R012","to_chain_id":"v141-c-R013","kind":"complementary_scope","from_refs":["v141-c-R012::phi::v141-c-R012-C001","v141-c-R012::phi::v141-c-R012-C002"],"to_refs":["v141-c-R013::phi::v141-c-R013-C001"],"evidence_ids":["v141-b-g01-ev-21","v141-b-g01-ev-28"],"rationale":"Peers' buying and selling roles across periods are compatible with the two types of listings, demand and surplus energy; each peer is not required to submit both buy and sell orders in every period."},{"connection_id":"v142-d-K003-L010","from_chain_id":"v141-c-R006","to_chain_id":"v141-c-R007","kind":"complementary_scope","from_refs":["v141-c-R006::phi::v141-c-R006-C003","v141-c-R006::phi::v141-c-R006-C004","v141-c-R006::phi::v141-c-R006-C005"],"to_refs":["v141-c-R007::phi::v141-c-R007-C004","v141-c-R007::phi::v141-c-R007-C005","v141-c-R007::phi::v141-c-R007-C006"],"evidence_ids":["v141-b-g01-ev-21","v141-b-g01-ev-23","v141-b-g01-ev-24"],"rationale":"The same arrangement of order permissions is represented separately in the demand and supply chains. The respective conditions concerning gate closure, network violations, and the example strategy are retained; shared evidence is not interpreted as indicating complete duplication of the provisions on the two sides."}],"annotation_policy":"Original D connections are annotations, not additional S edges.","empty_after_chain_suppression":false});
